// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address attacker, uint256 amount) public {
        vm.assume(attacker != address(this));
        vm.assume(attacker != address(0));

        uint256 seedFund = 1 ether;
        vm.deal(address(this), seedFund);
        (bool sent,) = address(c).call{value: seedFund}("");
        require(sent);

        amount = bound(amount, 0, seedFund);

        vm.deal(attacker, 1 ether);
        vm.startPrank(attacker);
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        assertTrue(!ok);
    }
}
